import hashlib
import math

class BloomFilter:
    """
    A simple Bloom filter implementation.

    This implementation calculates the size of the bit array and the number of hash functions
    based on the expected number of items and the desired false positive rate. 
    The design utilizes a list of booleans to represent the bit array and a series of 
    hash functions to determine the indices for adding and checking items.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        self.size = self.optimal_size(expected_items, false_positive_rate)
        self.hash_count = self.optimal_hash_count(self.size, expected_items)
        self.bit_array = [False] * self.size

    def optimal_size(self, n: int, p: float) -> int:
        """Calculate the optimal size of the bit array."""
        m = -(n * math.log(p)) / (math.log(2) ** 2)
        return int(m)

    def optimal_hash_count(self, m: int, n: int) -> int:
        """Calculate the optimal number of hash functions."""
        k = (m / n) * math.log(2)
        return int(k)

    def _hash(self, item: str, seed: int) -> int:
        """Generate a hash value using hashlib with the specified seed."""
        hash_result = hashlib.md5((str(seed) + item).encode()).hexdigest()
        return int(hash_result, 16) % self.size

    def add(self, item: str) -> None:
        """Add an item to the Bloom filter."""
        for i in range(self.hash_count):
            index = self._hash(item, i)
            self.bit_array[index] = True

    def contains(self, item: str) -> bool:
        """Check if an item is in the Bloom filter."""
        for i in range(self.hash_count):
            index = self._hash(item, i)
            if not self.bit_array[index]:
                return False
        return True

