class BloomFilter:
    """
    A class implementing a Bloom Filter, which is a space-efficient probabilistic data structure
    used to test whether an element is a member of a set. It may yield false positives but 
    never false negatives. The design uses a bit array and multiple hash functions to minimize 
    the probability of false positives based on expected items and a certain false positive rate.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        # Calculate the optimal size of the bit array and number of hash functions
        self.size = self._optimal_size()
        self.hash_count = self._optimal_hash_count()

        # Initialize the bit array
        self.bit_array = [0] * self.size

    def _optimal_size(self) -> int:
        """Calculate the optimal size of the bit array."""
        return math.ceil((-self.expected_items * math.log(self.false_positive_rate)) / (math.log(2) ** 2))

    def _optimal_hash_count(self) -> int:
        """Calculate the optimal number of hash functions."""
        return max(1, math.ceil(self.size / self.expected_items * math.log(2)))

    def _hashes(self, item: str) -> int:
        """Generate multiple hash values for the given item."""
        hash_values = set()
        for i in range(self.hash_count):
            # Create a unique hash for each index
            hash_value = int(hashlib.md5((item + str(i)).encode()).hexdigest(), 16) % self.size
            hash_values.add(hash_value)
        return hash_values

    def add(self, item: str) -> None:
        """Add an item to the Bloom filter."""
        for index in self._hashes(item):
            self.bit_array[index] = 1

    def contains(self, item: str) -> bool:
        """Check if an item is in the Bloom filter."""
        for index in self._hashes(item):
            if self.bit_array[index] == 0:
                return False
        return True

